import React from "react";
import { FaSearch, FaFilter } from "react-icons/fa";
import TechnicianItem from "./TechnicianItemComponent";
import FilterSheet from "./FilterSheetComponent";
import AuthCheck from "./AuthCheckComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";

class TechniciansPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      technicians: [],
      searchTerm: "",
      isFilterOpen: false,
      filterProvince: "",
      filterCity: "",
      filterSpecialty: "",
      loading: true,
      authenticated: false,
    };

    this.handleSearchChange = this.handleSearchChange.bind(this);
    this.openFilter = this.openFilter.bind(this);
    this.closeFilter = this.closeFilter.bind(this);
    this.applyFilter = this.applyFilter.bind(this);
    this.handleDelete = this.handleDelete.bind(this);
    this.handleToggleStatus = this.handleToggleStatus.bind(this);
    this.handleDetails = this.handleDetails.bind(this);
  }

  componentDidMount() {
    if (!AuthCheck()) {
      return;
    }

    this.setState(
      {
        authenticated: true,
      },
      () => {
        this.getTechnicians();
      }
    );
  }

  getTechnicians() {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/users`, {
      method: "GET",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("USERS API:", data);

        /*
         * اطلاعات کاربران داخل users است
         */
        const users = Array.isArray(data.users) ? data.users : [];

        const technicians = users.map((user) => ({
          id: user.id,

          name: `${user.name || ""} ${user.family || ""}`.trim(),

          /*
           * اگر active برابر 1 باشد آزاد
           * در غیر این صورت مسدود
           */
          status: Number(user.active) === 1 ? "free" : "blocked",

          /*
           * عکس
           */
          avatar: user.image
            ? `https://iranaserviceapp.ir/test/${user.image}`
            : `https://ui-avatars.com/api/?name=${encodeURIComponent(
                `${user.name || ""} ${user.family || ""}`
              )}&background=e9ecef&color=495057`,

          /*
           * اطلاعات اصلی را هم نگه می‌داریم
           */
          ...user,
        }));

        console.log("TECHNICIANS:", technicians);

        this.setState({
          technicians,
          loading: false,
        });
      })
      .catch((error) => {
        console.error("GET USERS ERROR:", error);

        this.setState({
          technicians: [],
          loading: false,
        });
      });
  }

  handleSearchChange(e) {
    this.setState({
      searchTerm: e.target.value,
    });
  }

  openFilter() {
    this.setState({
      isFilterOpen: true,
    });
  }

  closeFilter() {
    this.setState({
      isFilterOpen: false,
    });
  }

  applyFilter() {
    this.closeFilter();
  }

  handleDelete(id) {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/delete`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({
        id: id,
      }),
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("DELETE USER:", data);

        /*
         * فقط اگر API موفق بود از لیست حذف شود
         */
        if (String(data.status) === "1") {
          this.setState((prev) => ({
            technicians: prev.technicians.filter(
              (technician) => technician.id !== id
            ),
          }));
        }
      })
      .catch((error) => {
        console.error("DELETE USER ERROR:", error);
      });
  }

  handleToggleStatus(id, currentStatus) {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/active`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({
        id: id,
      }),
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("ACTIVE USER:", data);

        if (String(data.status) === "1") {
          const newStatus =
            currentStatus === "blocked" ? "free" : "blocked";

          this.setState((prev) => ({
            technicians: prev.technicians.map((technician) =>
              technician.id === id
                ? {
                    ...technician,
                    status: newStatus,
                    active: newStatus === "free" ? 1 : 0,
                  }
                : technician
            ),
          }));
        }
      })
      .catch((error) => {
        console.error("ACTIVE USER ERROR:", error);
      });
  }

  handleDetails(id) {
    console.log("جزئیات تعمیرکار:", id);
  }

  render() {
    if (!this.state.authenticated) {
      return null;
    }

    const {
      technicians,
      searchTerm,
      isFilterOpen,
      filterProvince,
      filterCity,
      filterSpecialty,
      loading,
    } = this.state;

    if (loading) {
      return (
        <div className="text-center text-muted py-5">
          در حال دریافت تعمیرکاران...
        </div>
      );
    }

    const search = searchTerm.trim();

    const filteredTechnicians = technicians.filter((technician) =>
      technician.name.includes(search)
    );

    return (
      <div dir="rtl">
        <div className="container px-3 pt-3">
          {/* جستجو */}
          <div className="d-flex align-items-center gap-2 border rounded-pill px-3 py-2 mb-3 bg-white">
            <input
              type="text"
              placeholder="جستجو..."
              value={searchTerm}
              onChange={this.handleSearchChange}
              className="form-control border-0 shadow-none text-end p-0"
            />

            <FaSearch
              className="text-secondary"
              size={16}
            />
          </div>

          {/* فیلتر */}
          <div className="d-flex justify-content-end mb-3">
            <button
              type="button"
              onClick={this.openFilter}
              className="btn btn-light border rounded-pill d-flex align-items-center gap-2 px-3 py-2"
            >
              <span>فیلتر</span>

              <FaFilter
                className="text-secondary"
                size={14}
              />
            </button>
          </div>

          {/* عنوان */}
          <div className="bg-light text-center rounded-3 py-3 mb-1">
            <span className="text-primary fw-semibold">
              تعمیرکاران
            </span>
          </div>

          {/* لیست */}
          <div>
            {filteredTechnicians.map((technician) => (
              <TechnicianItem
                key={technician.id}
                technician={technician}
                onDelete={this.handleDelete}
                onToggleStatus={this.handleToggleStatus}
                onDetails={this.handleDetails}
              />
            ))}

            {filteredTechnicians.length === 0 && (
              <div className="text-center text-muted py-5">
                موردی یافت نشد
              </div>
            )}
          </div>
        </div>

        <FilterSheet
          isOpen={isFilterOpen}
          onClose={this.closeFilter}
          onApply={this.applyFilter}
          province={filterProvince}
          city={filterCity}
          specialty={filterSpecialty}
          onProvinceChange={(e) =>
            this.setState({
              filterProvince: e.target.value,
            })
          }
          onCityChange={(e) =>
            this.setState({
              filterCity: e.target.value,
            })
          }
          onSpecialtyChange={(e) =>
            this.setState({
              filterSpecialty: e.target.value,
            })
          }
        />
      </div>
    );
  }
}

export default TechniciansPage;
